    static func privateHost(_ host:String)->Bool{if host=="localhost" || host=="127.0.0.1"{return true};let parts=host.split(separator:".");guard parts.count==4 else{return false};let values=parts.compactMap{part -> UInt8? in guard part=="0" || !part.hasPrefix("0") else{return nil};return UInt8(part)};guard values.count==4 else{return false};return values[0]==10 || (values[0]==192 && values[1]==168) || (values[0]==172 && (16...31).contains(values[1]))}
    func call(_ path:String,_ method:String="GET",_ value:[String:Any]?=nil)async throws->[String:Any]{let root=try Self.hubURL(data["hubURL"] as? String ?? "");let key=Vault.get("community");guard !key.isEmpty else{throw DeskError(message:"请先配置共享服务凭据")};var request=URLRequest(url:root.appendingPathComponent("v1/"+path));request.httpMethod=method;request.timeoutInterval=20;request.setValue("Bearer "+key,forHTTPHeaderField:"Authorization");if let value{request.httpBody=try JSONSerialization.data(withJSONObject:value);request.setValue("application/json",forHTTPHeaderField:"Content-Type")};let session=URLSession(configuration:.ephemeral,delegate:NoHubRedirect(),delegateQueue:nil);defer{session.invalidateAndCancel()};let(bytes,response)=try await session.data(for:request);guard bytes.count<=524288,let response=response as? HTTPURLResponse,response.statusCode==200 else{throw DeskError(message:"共享请求失败，请检查地址、凭据和服务状态")};guard let result=try JSONSerialization.jsonObject(with:bytes) as? [String:Any] else{throw DeskError(message:"共享响应格式无效")};return result}
    var favorites:[[String:Any]]{data["favorites"] as? [[String:Any]] ?? []}
