    static func apply(_ value:[String:Any],to original:Preferences)throws->(Preferences,Bool){guard value["schema"] as? String=="mojian-template-v1",let source=value["settings"] as? [String:Any],let kind=source["layout"] as? String,kind=="calendar" || DeskLayout(rawValue:kind) != nil else{throw DeskError(message:"模板版本或排版不支持")};let ratio=source["ratio"] as? Int ?? 67,goal=source["weeklyGoal"] as? Int ?? original.info.weeklyGoal;guard (40...75).contains(ratio),(1...999).contains(goal) else{throw DeskError(message:"模板数字超出范围")};var result=original;result.layout=DeskLayout(rawValue:kind) ?? .overview;result.customRatio=Double(ratio)/100;result.info.weeklyGoal=goal;let allowed=["plant","week","countdown","outdoor","status","note","nextEvent","commute","habits","inspiration","plugin"];var cards:[String]=[];for key in ["card1","card2"]{let card=source[key] as? String ?? "note";guard allowed.contains(card) else{throw DeskError(message:"模板卡片不支持")};cards.append(card)};result.info.cards=cards;let note=source["note"] as? String ?? original.note,state=source["deskStatus"] as? String ?? original.info.deskStatus ?? "专注中",detail=source["statusNote"] as? String ?? original.info.statusNote ?? "";guard note.count<=100,state.count<=30,detail.count<=30 else{throw DeskError(message:"模板文字过长")};result.info.artwork=kind=="calendar";result.note=note;result.info.deskStatus=state;result.info.statusNote=detail;return (result,kind=="calendar")}
    func preview(_ value:[String:Any]){do{let(settings,calendar)=try Self.apply(value,to:store.settings);var content=store.content;content.settings=settings;content.afterHours=calendar;let panel=NSAlert();panel.messageText=value["name"] as? String ?? "场景模板";panel.informativeText="应用将全刷一次，保留当前待办。";let image=NSImageView(frame:NSRect(x:0,y:0,width:640,height:384));image.image=ScreenRenderer.render(content);image.imageScaling = .scaleProportionallyUpOrDown;panel.accessoryView=image;panel.addButton(withTitle:"应用（全刷一次）");panel.addButton(withTitle:"取消");if panel.runModal() == .alertFirstButtonReturn{guard store.connected,!store.isSending else{status="请先连接设备";return};Task{await store.applyTemplate(settings,calendar:calendar)}}}catch{status=error.localizedDescription}}
    func exportTemplate(_ value:[String:Any]?=nil){do{let source=try value ?? Self.template(store.settings,store.afterHours,"我的桌面");let (clean,calendar)=try Self.apply(source,to:store.settings);let value=try Self.template(clean,calendar,source["name"] as? String ?? "我的桌面");let panel=NSSavePanel();panel.allowedContentTypes=[.json];panel.nameFieldStringValue="mojian-template.json";if panel.runModal() == .OK,let url=panel.url{try JSONSerialization.data(withJSONObject:value,options:[.prettyPrinted,.sortedKeys]).write(to:url,options:.atomic);status="模板已导出，不含待办、地址或密钥"}}catch{status=error.localizedDescription}}
    func importTemplate(){let panel=NSOpenPanel();panel.allowedContentTypes=[.json];guard panel.runModal() == .OK,let url=panel.url else{return};do{let bytes=try Data(contentsOf:url);guard bytes.count<=16384,let value=try JSONSerialization.jsonObject(with:bytes) as? [String:Any] else{throw DeskError(message:"模板文件无效或超过16KB")};let(clean,calendar)=try Self.apply(value,to:store.settings);let sanitized=try Self.template(clean,calendar,value["name"] as? String ?? "导入模板");guard favorites.count<12 else{throw DeskError(message:"最多十二个收藏")};data["favorites"]=favorites+[sanitized];save();preview(sanitized)}catch{status=error.localizedDescription}}
    func addHabit(_ title:String){let title=title.trimmingCharacters(in:.whitespacesAndNewlines);guard !title.isEmpty,title.count<=20,(store.settings.info.habits ?? []).count<3 else{status="习惯名称1至20字，最多三个";return};store.configureInformation{info in info.habits=(info.habits ?? [])+[DeskHabit(title:title)]}}
    func toggle(_ id:String){let today=dateText(Date(),"yyyy-MM-dd");store.configureInformation{info in guard var list=info.habits,let index=list.firstIndex(where:{$0.id==id}) else{return};if list[index].days.contains(today){list[index].days.removeAll{$0==today}}else{list[index].days.append(today)};list[index].days=Array(list[index].days.sorted().suffix(56));info.habits=list}}
    func removeHabit(_ id:String){store.configureInformation{$0.habits?.removeAll{$0.id==id}}}
    func capture()throws->[String:Any]{var shared=data["shared"] as? [String:Any] ?? [:];let stamp=Int(Date().timeIntervalSince1970*1000);var done=shared["completions"] as? [String:[String:Any]] ?? [:];for task in store.tasks{if task.done,task.skipped != true,let at=task.completedAt{let millis=Int(at.timeIntervalSince1970*1000);if let old=done[task.id],(old["stamp"] as? Int ?? 0)>=millis,old["deleted"] as? Bool==true || (old["completedAt"] as? Int ?? 0)>millis{continue};if done[task.id]?["completedAt"] as? Int != millis || done[task.id]?["deleted"] as? Bool==true{done[task.id]=["stamp":stamp,"completedAt":millis,"deleted":false]}}else if done[task.id] != nil,done[task.id]?["deleted"] as? Bool != true{done[task.id]?["deleted"]=true;done[task.id]?["stamp"]=stamp}};shared["completions"]=done
        for kind in ["habits","dates"]{var entries=shared[kind] as? [String:[String:Any]] ?? [:];var seen=Set<String>();let source:[[String:Any]]=kind=="habits" ? (store.settings.info.habits ?? []).map{["id":$0.id,"title":$0.title,"days":$0.days]}:store.settings.info.dates.map{["id":$0.id.uuidString.lowercased(),"title":$0.title,"date":dateText($0.date,"yyyy-MM-dd")]};for item in source{let id=item["id"] as! String;seen.insert(id);let previous=entries[id] ?? [:];var next=previous;next["title"]=item["title"];next["deleted"]=false;if kind=="dates"{next["date"]=item["date"]}else{var marks=next["days"] as? [String:[String:Any]] ?? [:];let checked=Set(item["days"] as? [String] ?? []);for day in Set(marks.keys).union(checked){let value=checked.contains(day);if marks[day]?["checked"] as? Bool != value{marks[day]=["stamp":stamp,"checked":value]}};let keys=marks.keys.sorted();for day in keys.dropLast(56){marks.removeValue(forKey:day)};next["days"]=marks};var x=previous,y=next;x.removeValue(forKey:"stamp");y.removeValue(forKey:"stamp");if !NSDictionary(dictionary:x).isEqual(to:y){next["stamp"]=stamp};entries[id]=next};for id in entries.keys where !seen.contains(id) && entries[id]?["deleted"] as? Bool != true{entries[id]?["deleted"]=true;entries[id]?["stamp"]=stamp};shared[kind]=entries};return shared}
    func exchange()async{guard !busy else{return};lastExchange=Date();busy=true;defer{busy=false};do{let captured=try capture();let settings=store.settings,tasks=store.tasks;let result=try await call("state","POST",["data":captured]);guard store.settings==settings,store.tasks==tasks else{status="本机同步期间发生更改，请再次同步；本机未覆盖";return};guard let shared=result["data"] as? [String:Any] else{throw DeskError(message:"共享数据无效")};var info=store.settings.info
            if let habits=shared["habits"] as? [String:[String:Any]]{info.habits=habits.compactMap{id,e in guard e["deleted"] as? Bool != true,let title=e["title"] as? String else{return nil};let marks=e["days"] as? [String:[String:Any]] ?? [:];return DeskHabit(id:id,title:title,days:marks.filter{$0.value["checked"] as? Bool==true}.keys.sorted())}}
            if let dates=shared["dates"] as? [String:[String:Any]]{let f=DateFormatter();f.dateFormat="yyyy-MM-dd";f.timeZone=WorkSchedule.calendar.timeZone;info.dates=dates.compactMap{id,e in guard e["deleted"] as? Bool != true,let uuid=UUID(uuidString:id),let title=e["title"] as? String,let text=e["date"] as? String,let date=f.date(from:text) else{return nil};return ImportantDate(id:uuid,title:title,date:date)}}
            if let value=shared["completions"],let bytes=try? JSONSerialization.data(withJSONObject:value){info.sharedCompletions=try? JSONDecoder().decode([String:SharedCompletion].self,from:bytes)};let changed=store.settings.info != info;store.settings.info=info;data["shared"]=shared;save();if changed{store.changed()};status="完成记录、习惯与日期已同步，完成量按ID去重"}catch{status=error.localizedDescription}}
    @Published var templates:[[String:Any]]=[]
    @Published var plugins:[[String:Any]]=[]
    @Published var messages:[[String:Any]]=[]
    func load(_ kind:String)async{guard !busy else{return};busy=true;defer{busy=false};do{let result=try await call(kind);let list=result["items"] as? [[String:Any]] ?? [];if kind=="templates"{templates=list}else if kind=="plugins"{plugins=list}else{messages=list};status="已读取 \(list.count) 项"}catch{status=error.localizedDescription}}
    func publish()async{do{_=try await call("templates","POST",Self.template(store.settings,store.afterHours,"共享桌面"));status="已发布模板，不含个人数据"}catch{status=error.localizedDescription}}
    func review(_ item:[String:Any],accept:Bool)async{guard let id=item["id"] as? String else{return};do{if accept{store.settings.note=String((item["text"] as? String ?? "").prefix(100));store.configureInformation{$0.cards=[$0.cards.first ?? "week","note"]}};_=try await call("messages/"+id,"PUT",["status":accept ? "accepted":"dismissed"]);await load("messages")}catch{status=error.localizedDescription}}
    func send(_ sender:String,_ text:String)async{guard !sender.isEmpty,sender.count<=30,!text.isEmpty,text.count<=100 else{status="署名1至30字，留言1至100字";return};do{_=try await call("messages","POST",["sender":sender,"text":text]);status="已进入收件箱，等待确认显示"}catch{status=error.localizedDescription}}
    func usePlugin(_ value:[String:Any]){do{let plugin=try DataPlugin.parse(value);store.configureInformation{$0.plugin=plugin;$0.cards=[$0.cards.first ?? "week","plugin"]}}catch{status=error.localizedDescription}}
}
final class NoHubRedirect:NSObject,URLSessionTaskDelegate,@unchecked Sendable {func urlSession(_ session:URLSession,task:URLSessionTask,willPerformHTTPRedirection response:HTTPURLResponse,newRequest request:URLRequest,completionHandler:@escaping(URLRequest?)->Void){completionHandler(nil)}}
struct SharedCompletion:Codable,Equatable{var stamp:Int64;var completedAt:Int64;var deleted:Bool}
struct DataPlugin:Codable,Equatable {
    var schema="mojian-card-v1";var name:String;var kind:String;var text:String?;var title:String?;var date:String?;var items:[String]?
    static func parse(_ value:[String:Any])throws->DataPlugin{let data=try JSONSerialization.data(withJSONObject:value);guard data.count<=5000 else{throw DeskError(message:"插件过长")};let p=try JSONDecoder().decode(Self.self,from:data);guard p.schema=="mojian-card-v1",p.name.count<=30,["text","countdown","daily"].contains(p.kind) else{throw DeskError(message:"插件格式不支持，不执行脚本")};switch p.kind{case "text":guard let t=p.text,t.count<=100 else{throw DeskError(message:"插件文字过长")};case "daily":guard let list=p.items,!list.isEmpty,list.count<=31,list.allSatisfy({$0.count<=100}) else{throw DeskError(message:"插件短句无效")};default:let f=ISO8601DateFormatter();f.formatOptions=[.withFullDate];guard let date=p.date,f.date(from:date) != nil,(p.title ?? "").count<=30 else{throw DeskError(message:"插件日期无效")}};return p}
    func display(at now:Date)->String{switch kind{case "daily":let values=items ?? [];return values.isEmpty ? "暂无内容":values[(WorkSchedule.calendar.ordinality(of:.day,in:.year,for:now) ?? 1)%values.count];case "countdown":let f=DateFormatter();f.dateFormat="yyyy-MM-dd";f.timeZone=WorkSchedule.calendar.timeZone;guard let date=f.date(from:date ?? "") else{return "日期无效"};return InformationLogic.countdown(ImportantDate(title:title ?? name,date:date),at:now);default:return text ?? ""}}
}
